mc(d,8,'Một compound AI system có retriever, tool và nhiều lần gọi model cần version/rollback ở đơn vị nào?','Cả pipeline cùng các thành phần cấu hình liên quan','Chỉ một file weights','Chỉ git SHA mà bỏ index/model snapshot','Chỉ giao diện chatbot','Đơn vị vận hành là toàn hệ thống: prompt, model snapshot, index và tool schema cùng tác động kết quả.')
mc(d,9,'Vì sao test output bằng so khớp chuỗi vẫn dễ chập chờn khi temperature=0?','Thay đổi batching và thứ tự phép cộng floating-point có thể đổi output','Temperature=0 đồng nghĩa mọi lỗi do mạng','Model bắt buộc trả string rỗng ở nhiệt độ 0','Chỉ có seed quyết định toàn bộ execution','Temperature=0 không bảo đảm output identical; gate nên dựa tỷ lệ pass cùng độ tin cậy thay string equality.')
mc(d,13,'Kết quả eval của prompt version chỉ có ý nghĩa đầy đủ khi gắn với điều gì?','Model snapshot đã chạy eval','Tên chủ sở hữu giao diện','Số ticket bất kỳ không liên quan','Một alias latest có thể đổi mà không log','Prompt được tune cho model cụ thể; cặp prompt_version và model_snapshot là đơn vị có ý nghĩa.')
mc(d,17,'Commit message prompt nào cung cấp thông tin hữu ích cho review sau này?','Nêu thay đổi, bằng chứng lý do và đánh đổi đo được','Chỉ viết update prompt','Chỉ ghi try again','Chỉ ghi thời gian mà không nội dung','Khuôn ba phần là đổi gì, vì sao/bằng chứng nào và đánh đổi đo được, giúp hiểu ý định ngoài text diff.')
mc(d,19,'Registry cho PM sửa nhanh nhưng đội muốn giữ đường thoát và CI đọc được artifact. Cách kết hợp nào phù hợp?','Sync prompt từ registry về git qua webhook','Chỉ giữ prompt trong UI không export','Xóa mọi bản backup sau mỗi lần sửa','Bỏ CI vì registry đã có version','Mô hình lai giữ tốc độ registry cùng bản sao git để backup và CI, giảm lệ thuộc vendor.')
mc(d,23,'Local prompt cache kết hợp stale-while-revalidate giúp ích gì khi TTL hết?','Trả bản cũ ngay và cập nhật nền để request không chờ registry','Bắt user chờ registry mỗi request','Xóa mọi fallback prompt','Tự đổi model snapshot không cần gate','Stale-while-revalidate tránh registry nằm trên critical path; fallback và prefetch bổ sung độ bền.')
mc(d,23,'Tăng TTL local prompt cache có đánh đổi vận hành nào?','Version mới và rollback có thể lan ra toàn cụm chậm hơn','Rollback luôn có hiệu lực đồng thời tức thì','Mọi eval tự chạy nhiều lần hơn','Không còn cần model pin','TTL dài giảm fetch nhưng làm chậm propagation; chọn TTL liên quan RTO rollback toàn cụm.')
mc(d,26,'Bất kỳ user registry nào cũng đổi được label production tạo rủi ro gì?','Đường thay đổi hành vi production bỏ qua kiểm soát release','Chỉ làm commit message dài hơn','Tự bảo đảm đã pass eval gate','Chỉ giảm tốc độ đọc prompt','Production label cần role được cấp, eval gate, audit và cảnh báo vì thay prompt không cần app deployment.')
mc(d,28,'Regression gate nên chạy khi PR chạm những thành phần nào?','Prompt, model hoặc retrieval config','Chỉ code Python còn prompt thì bỏ qua','Chỉ README','Chỉ file ảnh dashboard','Thay prompt, model hay retrieval đều đổi hành vi nên cần eval trên golden set và so baseline trước merge.')
