mc(d,41,'Để tối đa prefix-cache reuse, nội dung prompt nên sắp xếp ra sao?','Phần ổn định trước, phần biến động sau','Timestamp và request UUID đặt đầu system prompt','Đảo tool order ngẫu nhiên mỗi request','User-specific text luôn đứng trước mọi policy chung','Prefix cache bị phá từ vị trí thay đổi trở đi; phần ổn định trước giữ tiền tố dùng lại.')
mc(d,45,'Cache read bằng 0 qua nhiều request dự kiến cùng prefix. Nên kiểm tra điều gì?','Timestamp/UUID hoặc serialization/tool order không xác định ở prefix','Chỉ độ phân giải màn hình user','Chỉ số version Python không liên quan prompt','Chỉ tên alias có bao nhiêu ký tự','Silent invalidators gồm timestamp, UUID, nondeterministic dump và tool set biến đổi; cần deterministic render hoặc chuyển phần động về sau.')
mc(d,49,'Vì sao bảng giá dùng tính cost lịch sử cần có version?','Không được định giá lại quá khứ bằng giá hôm nay khi so sánh theo thời gian','Để luôn áp dụng giá cao nhất','Để bỏ tag prompt_version','Để token count tự thay đổi sau mỗi tháng','Giá thay đổi theo thời gian; version bảng giá giữ attribution và so sánh cost lịch sử đúng ngữ cảnh.')
mc(d,50,'Cost/request tăng nhưng prompt không dài hơn. Metric nào giúp phân biệt nguyên nhân do cache?','Cache read/hit rate theo prompt_version','Chỉ số lượng PR trong repo','Chỉ model parameter count','Chỉ số dòng YAML','Cache hit giảm có thể làm cost tăng độc lập độ dài; cần theo dõi cost, token và cache cùng version.')
mc(d,52,'Thay ngưỡng guardrail mà giữ nguyên prompt text nên được quản lý thế nào?','Version, review, eval và audit như thay đổi hành vi trong cùng context bundle','Chỉ xem là chỉnh cấu hình không cần test','Cho phép sửa trực tiếp production không log','Không thể rollback vì không phải code','Guardrail threshold quyết định hành vi an toàn; tách version khỏi prompt làm bundle không tái hiện đúng hệ thống.')
mc(d,62,'Một quy trình chỉ dùng cho một loại việc nên được đặt ở tầng context nào?','Nạp khi cần thay vì luôn nằm trong mọi request','Luôn đặt đầu system prompt cho mọi task','Nhân bản vào mọi tool result','Chỉ lưu trong trí nhớ người vận hành','Facts luôn liên quan thuộc tầng luôn nạp; procedures chỉ phục vụ một loại việc nên lazy-load để tiết kiệm token và ổn định prefix.')
